    images: ["/products/axa-pdp/X000008528/black/1.jpg", "/products/axa-pdp/X000008528/black/2.jpg", "/products/axa-pdp/X000008528/black/3.jpg", "/products/axa-pdp/X000008528/black/4.jpg", "/products/axa-pdp/X000008528/black/5.jpg", "/products/axa-pdp/X000008528/black/6.jpg", "/products/axa-pdp/X000008528/black/7.jpg", "/products/axa-pdp/X000008528/black/8.jpg"],
