    image: "/products/axa-pdp/X000009563/black/1.jpg",
    images: ["/products/axa-pdp/X000009563/black/1.jpg", "/products/axa-pdp/X000009563/black/2.jpg", "/products/axa-pdp/X000009563/black/3.jpg", "/products/axa-pdp/X000009563/black/4.jpg", "/products/axa-pdp/X000009563/black/5.jpg", "/products/axa-pdp/X000009563/black/6.jpg", "/products/axa-pdp/X000009563/black/7.jpg", "/products/axa-pdp/X000009563/black/8.jpg", "/products/axa-pdp/X000009563/forage/1.jpg", "/products/axa-pdp/X000009563/forage/2.jpg", "/products/axa-pdp/X000009563/forage/3.jpg", "/products/axa-pdp/X000009563/forage/4.jpg", "/products/axa-pdp/X000009563/forage/5.jpg", "/products/axa-pdp/X000009563/forage/6.jpg", "/products/axa-pdp/X000009563/forage/7.jpg", "/products/axa-pdp/X000009563/forage/8.jpg"],
