    storySections: [{"titleKo": "Norvan Short 3\"", "bodyKo": "Light, breathable, and built for speed, the three-inch Norvan is made for trail runners who fly down technical trails. Made from 100% recycled Diem™ polyester, they’re soft, comfortable and have the freedom of stretch. The minimal inseam, ergonomic patterning, and a split hem eliminate restriction, and a built-in brief wicks moisture. The breathable waistband is designed for comfort and security on extended runs, and a zippered back pocket provides bounce-free carry for gels.", "image": "/products/axa-pdp/X000010613/mallow/1.jpg"}, {"titleKo": "핏: 슬림 핏", "bodyKo": "가슴, 허리, 힙, 허벅지를 따라 몸에 가깝게 밀착되도록 설계한 슬림 핏입니다. 부피를 줄인 로우 프로파일 디자인이 몸의 움직임을 자연스럽게 따라가며, 아우터 레이어 아래에서도 편안하게 착용됩니다.", "image": "/products/axa-pdp/X000010613/mallow/2.jpg", "reverse": true}, {"titleKo": "기술적 특징", "bodyKo": "Breathable · Lightweight · Air permeable · Water repellent · Antimicrobial", "image": "/products/axa-pdp/X000010613/mallow/3.jpg"}, {"titleKo": "구조", "bodyKo": "Diem™ polyester dries fast, is lightweight, durable, highly breathable, and comfortable next-to-skin · Integrated stretch polyester brief wicks moisture and has an anti-microbial treatment to manage odour", "image": "/products/axa-pdp/X000010613/mallow/4.jpg", "reverse": true}, {"titleKo": "디자인 및 핏", "bodyKo": "Regular fit provides freedom of movement · Garment Inseam: Size 4 is 3\"/8cm — Inseam varies by size", "image": "/products/axa-pdp/X000010613/mallow/5.jpg"}, {"titleKo": "원단 처리", "bodyKo": "FC0-DWR(내구성 발수) 마감이 습기를 효과적으로 막아줍니다.", "image": "/products/axa-pdp/X000010613/mallow/6.jpg", "reverse": true}, {"titleKo": "밑단 구성", "bodyKo": "측면 밑단이 분할되어 움직임이 가능함", "image": "/products/axa-pdp/X000010613/shincha/1.jpg"}, {"titleKo": "로고 및 라벨 구성", "bodyKo": "반사 로고는 저조도 상황에서도 가시성을 높여줍니다.", "image": "/products/axa-pdp/X000010613/shincha/2.jpg", "reverse": true}, {"titleKo": "패터닝", "bodyKo": "자유로운 움직임을 위한 입체 패터닝", "image": "/products/axa-pdp/X000010613/shincha/3.jpg"}, {"titleKo": "포켓 구성", "bodyKo": "Zippered centre-back top-entry pocket", "image": "/products/axa-pdp/X000010613/shincha/4.jpg", "reverse": true}, {"titleKo": "지속 가능성", "bodyKo": "Contains materials produced through processes that meet bluesign® criteria · Body - recycled content · Lining - bluepass Material · This article was treated with an anti-odour biocidal product (Silvadur™ ) · PFAS (Per- and polyfluoroalkyl substances) Compliant", "image": "/products/axa-pdp/X000010613/shincha/5.jpg"}, {"titleKo": "허리 및 벨트 구성", "bodyKo": "Drawcord provides a secure, comfortable fit", "image": "/products/axa-pdp/X000010613/shincha/6.jpg", "reverse": true}],
