    storySections: [{"titleKo": "Sima Shirt SS", "bodyKo": "Keep your cool on your next hike in the Sima Shirt. Lightweight and airy, its durable recycled polyester fabric provides UPF 50+ sun protection. Smart, trail-specific features like a mesh back panel and chest pockets you can use without taking off your pack make it an essential for hikes under the hot sun.", "image": "/products/axa-pdp/X000009498/alpine-blue/1.jpg"}, {"titleKo": "Fit: Relaxed", "bodyKo": "This fit is cut loosely through the chest, waist, hip, and thigh. Relaxed without sacrificing structure and clean lines, it offers comfort and freedom of movement with a more casual look.", "image": "/products/axa-pdp/X000009498/alpine-blue/2.jpg", "reverse": true}, {"titleKo": "기술적 특징", "bodyKo": "Breathable · Lightweight · Durable", "image": "/products/axa-pdp/X000009498/alpine-blue/3.jpg"}, {"titleKo": "구조", "bodyKo": "Dynamically placed shoulder seams improve freedom of movement and are comfortable under pack straps · Light, durable recycled polyester double weave is breathable and stretchy", "image": "/products/axa-pdp/X000009498/alpine-blue/4.jpg", "reverse": true}, {"titleKo": "밑단 구성", "bodyKo": "Side slits allow ease of movement", "image": "/products/axa-pdp/X000009498/alpine-blue/5.jpg"}, {"titleKo": "패터닝", "bodyKo": "자유로운 움직임을 위한 입체 패터닝", "image": "/products/axa-pdp/X000009498/alpine-blue/6.jpg", "reverse": true}, {"titleKo": "포켓 구성", "bodyKo": "Two side entry chest pockets with concealed zippers", "image": "/products/axa-pdp/X000009498/habitat/1.jpg"}, {"titleKo": "지속 가능성", "bodyKo": "Recycled content · PFAS (Per- and polyfluoroalkyl substances) Compliant", "image": "/products/axa-pdp/X000009498/habitat/2.jpg", "reverse": true}, {"titleKo": "UPF 등급", "bodyKo": "UPF 50+, EN 13758-2, AS4399:2020, GB/T 18830-2009. 덮힌 부분만 보호됩니다. 사용하거나 늘어나거나 젖으면 보호 기능이 저하될 수 있습니다.", "image": "/products/axa-pdp/X000009498/habitat/3.jpg"}, {"titleKo": "지퍼 및 플라이 구성", "bodyKo": "Snap front placket for easy on-and-off", "image": "/products/axa-pdp/X000009498/habitat/4.jpg", "reverse": true}, {"titleKo": "소재", "bodyKo": "Body: Recycled polyester plain weave w/mech stretch, 92gsm, UPF 40, wrinkle finish - 100% Polyester · Origin of fabric: JAPAN · Origin of dyeing: JAPAN · Origin of Manufacture: VIETNAM · May release plastic microfibres into the environment when washing", "image": "/products/axa-pdp/X000009498/habitat/5.jpg"}, {"titleKo": "관리 방법", "bodyKo": "Machine wash gentle low · Tumble dry normal low · Do not bleach · Wash dark colours separately · Do not dry clean · Iron low · Do not use fabric softener", "image": "/products/axa-pdp/X000009498/habitat/6.jpg", "reverse": true}],
